solution.relative_distance.zig:
const std = @import("std");
pub const Family = struct { parent: []const u8, children: []const []const u8 };
fn eq(a: []const u8, b: []const u8) bool {
    return std.mem.eql(u8, a, b);
}
fn exists(f: []const Family, p: []const u8) bool {
    for (f) |r| {
        if (eq(r.parent, p)) return true;
        for (r.children) |c| {
            if (eq(c, p)) return true;
        }
    }
    return false;
}
fn linked(f: []const Family, a: []const u8, b: []const u8) bool {
    for (f) |r| {
        var aa = eq(r.parent, a);
        var bb = eq(r.parent, b);
        for (r.children) |c| {
            aa = aa or eq(c, a);
            bb = bb or eq(c, b);
        }
        if (aa and bb) return true;
    }
    return false;
}
pub fn degree(a: std.mem.Allocator, f: []const Family, from: []const u8, to: []const u8) !usize {
    if (!exists(f, from)) return error.PersonANotInFamilyTree;
    if (!exists(f, to)) return error.PersonBNotInFamilyTree;
    var names = std.array_list.Managed([]const u8).init(a);
    defer names.deinit();
    for (f) |r| {
        try names.append(r.parent);
        try names.appendSlice(r.children);
    }
    const distances = try a.alloc(usize, names.items.len);
    defer a.free(distances);
    @memset(distances, std.math.maxInt(usize));
    for (names.items, 0..) |p, i| {
        if (eq(p, from)) distances[i] = 0;
    }
    var step: usize = 0;
    while (step <= names.items.len) : (step += 1) {
        for (names.items, 0..) |p, i| {
            if (distances[i] != step) continue;
            if (eq(p, to)) return step;
            for (names.items, 0..) |q, j| {
                if (distances[j] == std.math.maxInt(usize) and linked(f, p, q)) distances[j] = step + 1;
            }
        }
    }
    return error.NoConnection;
}

