// Test scenarios adapted from the MIT-licensed Exercism Python track and
// exercism/problem-specifications (4289d4ec9ed947cd785939ab82c479bb8d4f2cc7).
const std = @import("std");
const t = std.testing;
const m = @import("relative_distance.zig");
test "siblings parents partners and unrelated people" {
    const f = [_]m.Family{ .{ .parent = "Helena", .children = &.{ "Isla", "Tariq" } }, .{ .parent = "Isla", .children = &.{"Uma"} }, .{ .parent = "Tariq", .children = &.{"Morphy"} }, .{ .parent = "Erdos", .children = &.{"Kevin"} }, .{ .parent = "Shusaku", .children = &.{"Kevin"} } };
    try t.expectEqual(@as(usize, 1), try m.degree(t.allocator, &f, "Isla", "Tariq"));
    try t.expectEqual(@as(usize, 2), try m.degree(t.allocator, &f, "Uma", "Tariq"));
    try t.expectEqual(@as(usize, 2), try m.degree(t.allocator, &f, "Erdos", "Shusaku"));
    try t.expectEqual(@as(usize, 0), try m.degree(t.allocator, &f, "Uma", "Uma"));
    try t.expectError(error.NoConnection, m.degree(t.allocator, &f, "Uma", "Kevin"));
    try t.expectError(error.PersonANotInFamilyTree, m.degree(t.allocator, &f, "?", "Kevin"));
    try t.expectError(error.PersonBNotInFamilyTree, m.degree(t.allocator, &f, "Uma", "?"));
}
